async ({ workspace: { read, search } }) => {
  const [cs, rk, pre, gitr] = await Promise.all([
    read("src/functions/command-source.ts", { format: "raw" }),
    search("ResultRendererKey", { path: "src", limit: 20, contextLines: 0 }),
    search("PitNpmInstallOptions|PitProcessOptions \\{|PitNpmTestOptions", { path: "src/functions/global-contract-preamble.d.ts", regex: true, contextLines: 12 }),
    search("\"git\\.tag\"|git\\.tag", { path: "src", regex: true, limit: 30, contextLines: 1 }),
  ]);
  const sl = (r: any) => r.matches?.map((m: any) => `${m.file}:${m.line}: ${m.text?.slice(0, 160)}`) ?? r;
  return { cs: cs.content, rk: sl(rk), pre: pre.matches?.map((m: any) => m.context ?? m.text), gitr: sl(gitr) };
}
